import{_ as i,o as e,c as l,a2 as r}from"./chunks/framework.BXzK3EA4.js";const S=JSON.parse('{"title":"前端安全","description":"7 年前端面试必问。本文按攻击 → 防御 → 实战三段式组织，配真实代码（来自简历项目）。","frontmatter":{},"headers":[],"relativePath":"security/index.md","filePath":"security/index.md","lastUpdated":1793930980000}'),t={name:"security/index.md"};function o(n,a,s,c,h,f){return e(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="前端安全" tabindex="-1">前端安全 <a class="header-anchor" href="#前端安全" aria-label="Permalink to &quot;前端安全&quot;">​</a></h1><blockquote><p>7 年前端面试必问。本文按攻击 → 防御 → 实战三段式组织，配真实代码（来自简历项目）。</p></blockquote><h2 id="📚-章节列表" tabindex="-1">📚 章节列表 <a class="header-anchor" href="#📚-章节列表" aria-label="Permalink to &quot;📚 章节列表&quot;">​</a></h2><ol><li><a href="./5-checklist">安全检查清单</a></li><li><a href="./6-clickjacking">Clickjacking（点击劫持）</a></li><li><a href="./7-csp">CSP（Content Security Policy）</a></li><li><a href="./8-csrf-samesite">点击劫持防御：CSRF Token + SameSite</a></li><li><a href="./9-csrf">CSRF（跨站请求伪造）</a></li><li><a href="./10-deps-security">第三方依赖安全</a></li><li><a href="./11-iframe-security">iframe 安全</a></li><li><a href="./12-input-validation">输入验证与防注入</a></li><li><a href="./14-mitm">中间人攻击（MITM）</a></li><li><a href="./15-monitoring">监控与响应</a></li><li><a href="./16-oauth">Token 与 OAuth</a></li><li><a href="./17-password-deep">密码安全</a></li><li><a href="./18-project-pitfalls">项目踩过的坑</a></li><li><a href="./19-threats">安全威胁全景</a></li><li><a href="./20-xss">XSS（跨站脚本攻击）</a></li></ol><h2 id="📝-小结" tabindex="-1">📝 小结 <a class="header-anchor" href="#📝-小结" aria-label="Permalink to &quot;📝 小结&quot;">​</a></h2><ul><li>安全按「<strong>威胁模型 → 单点攻击 → 防御 → 监控 → 实战</strong>」组织,XSS / CSRF / CSP / Clickjacking 是必答四件套。</li><li>XSS 三类(存储型/反射型/DOM 型)与防御手段(转义 + CSP + 避免 innerHTML)的对应关系要能画出来。</li><li>CSRF 防御三件套:Token、SameSite Cookie、校验 Origin/Referer;要讲清为什么「自定义请求头」也能防。</li><li>前端安全的边界:<strong>前端只能减少攻击面,真正的防线在服务端</strong>(校验、鉴权、参数化查询)。</li><li>面试高分点:讲「我们项目里做的具体事」——CSP 落地、依赖漏洞扫描、token 存储位置选择(为什么不用 localStorage)。</li><li>加分:结合最近一次安全漏洞或事故讲「发现 → 修复 → 复盘」的完整闭环。</li></ul>',6)])])}const u=i(t,[["render",o]]);export{S as __pageData,u as default};
